ALTER TABLE hocalist.role_profiles
  ADD COLUMN image_media_id uuid REFERENCES hocalist.media_images(id);

-- The reference must be a ready, profile-purpose image owned by the membership's
-- user. It can never point at another user's asset or another purpose.
CREATE FUNCTION hocalist.profile_avatar_validate() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_owner uuid;
BEGIN
  IF NEW.image_media_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.user_id INTO v_owner FROM hocalist.memberships m
    WHERE m.id = NEW.membership_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'invalid_membership' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM hocalist.media_images mi
    WHERE mi.id = NEW.image_media_id
      AND mi.owner_user_id = v_owner
      AND mi.state = 'ready'
      AND mi.purpose = 'profile') THEN
    RAISE EXCEPTION 'invalid_media_reference' USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END; $$;

CREATE TRIGGER profile_avatar_validate_reference
  BEFORE INSERT OR UPDATE OF image_media_id ON hocalist.role_profiles
  FOR EACH ROW EXECUTE FUNCTION hocalist.profile_avatar_validate();

-- Sets or clears the caller's own role-profile avatar at an expected revision.
-- `p_role` selects the buyer or seller membership; `p_key` is a stable caller
-- operation key so an uncertain retry replays the committed result instead of
-- applying twice. A restriction on either role blocks the change.
CREATE FUNCTION hocalist.profile_avatar_update(
  p_role text,
  p_key text,
  p_expected_revision bigint,
  p_media_id uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_membership hocalist.memberships%ROWTYPE;
  v_row hocalist.role_profiles%ROWTYPE;
  v_receipt hocalist.command_receipts%ROWTYPE;
  v_hash text;
  v_result jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF p_role IS NULL OR p_role NOT IN ('buyer','seller') THEN
    RAISE EXCEPTION 'invalid_field: role' USING ERRCODE='22023';
  END IF;
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 128
     OR p_expected_revision IS NULL OR p_expected_revision < 1 THEN
    RAISE EXCEPTION 'invalid_command' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM hocalist.profiles WHERE id = v_user FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'onboarding_seed_required' USING ERRCODE='42501';
  END IF;
  -- A restriction cannot be bypassed by switching roles.
  IF EXISTS (
       SELECT 1 FROM hocalist.memberships
       WHERE user_id = v_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_membership FROM hocalist.memberships
    WHERE user_id = v_user AND role = p_role AND status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'membership_required' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (
       SELECT 1 FROM hocalist.role_profiles WHERE membership_id = v_membership.id) THEN
    RAISE EXCEPTION 'profile_required' USING ERRCODE='P0002';
  END IF;
  IF p_media_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM hocalist.media_images mi
       WHERE mi.id = p_media_id
         AND mi.owner_user_id = v_user
         AND mi.state = 'ready'
         AND mi.purpose = 'profile') THEN
    RAISE EXCEPTION 'invalid_media_reference' USING ERRCODE='22023';
  END IF;

  v_hash := encode(
    sha256(convert_to(
      p_role || '|' || p_expected_revision::text || '|' || coalesce(p_media_id::text, ''),
      'UTF8')), 'hex');
  SELECT * INTO v_receipt FROM hocalist.command_receipts
    WHERE user_id = v_user AND operation = 'avatar.update' AND idempotency_key = p_key;
  IF FOUND THEN
    IF v_receipt.request_hash <> v_hash THEN
      RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001';
    END IF;
    RETURN v_receipt.result;
  END IF;

  UPDATE hocalist.role_profiles
    SET image_media_id = p_media_id,
        revision = revision + 1,
        updated_at = now()
    WHERE membership_id = v_membership.id AND revision = p_expected_revision
    RETURNING * INTO v_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'revision_conflict' USING ERRCODE='P0001';
  END IF;
  v_result := jsonb_build_object(
    'membership_id', v_row.membership_id,
    'image_media_id', v_row.image_media_id,
    'revision', v_row.revision);
  INSERT INTO hocalist.command_receipts(
    user_id, operation, idempotency_key, request_hash, result)
  VALUES (v_user, 'avatar.update', p_key, v_hash, v_result);
  RETURN v_result;
END; $$;

-- Public avatar reference for one active membership. The caller must hold an
-- active, unrestricted membership in either role; a restricted target user is
-- never projected.
CREATE FUNCTION hocalist.member_avatar(p_membership uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_image uuid;
  v_target_user uuid;
  v_target_revision bigint;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF p_membership IS NULL THEN
    RAISE EXCEPTION 'invalid_field: membership' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (
       SELECT 1 FROM hocalist.memberships
       WHERE user_id = v_user AND status = 'active')
     OR EXISTS (
       SELECT 1 FROM hocalist.memberships
       WHERE user_id = v_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'membership_required' USING ERRCODE='42501';
  END IF;
  SELECT rp.image_media_id, rp.revision, m.user_id
    INTO v_image, v_target_revision, v_target_user
  FROM hocalist.role_profiles rp
  JOIN hocalist.memberships m ON m.id = rp.membership_id
  WHERE rp.membership_id = p_membership AND m.status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found' USING ERRCODE='P0002';
  END IF;
  IF EXISTS (
       SELECT 1 FROM hocalist.memberships
       WHERE user_id = v_target_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'profile_not_found' USING ERRCODE='P0002';
  END IF;
  RETURN jsonb_build_object(
    'membership_id', p_membership,
    'image_media_id', v_image,
    'revision', v_target_revision);
END; $$;

-- Extend the media read rule with referenced profile avatars. The referenced
-- asset is public-facing by intent; unreferenced profile drafts stay private,
-- and neither a restricted target user nor an unreferenced image is served.
-- Purpose helpers installed by other additive migrations are dispatched to only
-- when present, so apply order between 011 and 101 does not matter.
CREATE FUNCTION hocalist.media_read_profile(p_user uuid, p_image uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1 FROM hocalist.role_profiles rp
    JOIN hocalist.memberships m ON m.id = rp.membership_id
    WHERE rp.image_media_id = p_image
      AND m.status = 'active'
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.memberships r
        WHERE r.user_id = m.user_id AND r.status IN ('restricted','disabled')));
$$;

CREATE OR REPLACE FUNCTION hocalist.media_gateway(p_user uuid, p_action text, p_input jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  m hocalist.media_images%ROWTYPE;
  image_id uuid;
  purpose text;
  n integer;
  v_allowed boolean;
BEGIN
  IF p_user IS NULL
     OR NOT EXISTS (SELECT 1 FROM hocalist.memberships WHERE user_id = p_user AND status = 'active')
     OR EXISTS (SELECT 1 FROM hocalist.memberships WHERE user_id = p_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'media_access_denied' USING ERRCODE='42501';
  END IF;
  INSERT INTO hocalist.media_windows(user_id, started_at, calls)
  VALUES (p_user, now(), 1)
  ON CONFLICT (user_id) DO UPDATE SET
    calls = CASE WHEN media_windows.started_at < now() - interval '1 minute' THEN 1 ELSE media_windows.calls + 1 END,
    started_at = CASE WHEN media_windows.started_at < now() - interval '1 minute' THEN now() ELSE media_windows.started_at END
  RETURNING calls INTO n;
  IF n > 60 THEN RAISE EXCEPTION 'media_rate_limit'; END IF;
  IF p_action = 'begin' THEN
    purpose := p_input->>'purpose';
    IF purpose IN ('offer','store') AND NOT EXISTS (
      SELECT 1 FROM hocalist.memberships WHERE user_id = p_user AND role = 'seller' AND status = 'active') THEN
      RAISE EXCEPTION 'media_access_denied' USING ERRCODE='42501';
    END IF;
    PERFORM 1 FROM hocalist.profiles WHERE id = p_user FOR UPDATE;
    SELECT * INTO m FROM hocalist.media_images
      WHERE owner_user_id = p_user AND intent_key = (p_input->>'key')::uuid;
    IF FOUND THEN
      IF m.purpose <> purpose OR m.content_hash <> p_input->>'hash' THEN
        RAISE EXCEPTION 'idempotency_conflict';
      END IF;
    ELSE
      IF (SELECT count(*) FROM hocalist.media_images
          WHERE owner_user_id = p_user AND created_at > now() - interval '1 hour') >= 60 THEN
        RAISE EXCEPTION 'media_rate_limit';
      END IF;
      INSERT INTO hocalist.media_images(owner_user_id, intent_key, purpose, content_hash)
      VALUES (p_user, (p_input->>'key')::uuid, purpose, p_input->>'hash')
      RETURNING * INTO m;
    END IF;
  ELSIF p_action = 'complete' THEN
    UPDATE hocalist.media_images
      SET state = 'ready', size_bytes = (p_input->>'size')::integer,
          width = (p_input->>'width')::integer, height = (p_input->>'height')::integer
      WHERE id = (p_input->>'id')::uuid AND owner_user_id = p_user
        AND state IN ('pending','ready')
      RETURNING * INTO m;
    IF NOT FOUND THEN RAISE EXCEPTION 'media_not_found' USING ERRCODE='P0002'; END IF;
  ELSIF p_action = 'read' THEN
    image_id := (p_input->>'id')::uuid;
    SELECT * INTO m FROM hocalist.media_images WHERE id = image_id AND state = 'ready';
    IF NOT FOUND THEN RAISE EXCEPTION 'media_not_found' USING ERRCODE='P0002'; END IF;
    IF m.owner_user_id <> p_user THEN
      v_allowed :=
        (m.purpose = 'store' AND EXISTS (
          SELECT 1 FROM hocalist.store_listings l
          JOIN hocalist.memberships s ON s.id = l.seller_profile_id
          WHERE l.image_media_ids ? image_id::text
            AND l.status = 'active' AND l.moderation_status = 'approved' AND s.status = 'active'))
        OR (m.purpose = 'offer' AND EXISTS (
          SELECT 1 FROM hocalist.offer_revisions r
          JOIN hocalist.offers o ON o.id = r.offer_id
          JOIN hocalist.requests q ON q.id = o.request_id
          WHERE r.image_media_ids ? image_id::text AND q.buyer_user_id = p_user));
      IF NOT v_allowed
         AND to_regprocedure('hocalist.media_read_chat(uuid,uuid)') IS NOT NULL THEN
        v_allowed := hocalist.media_read_chat(p_user, image_id);
      END IF;
      IF NOT v_allowed
         AND to_regprocedure('hocalist.media_read_profile(uuid,uuid)') IS NOT NULL THEN
        v_allowed := hocalist.media_read_profile(p_user, image_id);
      END IF;
      IF NOT v_allowed THEN
        RAISE EXCEPTION 'media_access_denied' USING ERRCODE='42501';
      END IF;
    END IF;
  ELSE
    RAISE EXCEPTION 'invalid_action' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object(
    'id', m.id,
    'path', m.owner_user_id::text || '/' || m.id::text || '.jpg',
    'state', m.state);
END; $$;

REVOKE ALL ON FUNCTION hocalist.profile_avatar_validate(),
  hocalist.profile_avatar_update(text,text,bigint,uuid),
  hocalist.member_avatar(uuid),
  hocalist.media_read_profile(uuid,uuid)
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION hocalist.media_gateway(uuid,text,jsonb)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.profile_avatar_update(text,text,bigint,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION hocalist.member_avatar(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION hocalist.media_gateway(uuid,text,jsonb) TO service_role;

DO $hocalist_profile_avatar_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_attribute
    WHERE attrelid = 'hocalist.role_profiles'::regclass
      AND attname = 'image_media_id' AND NOT attisdropped) THEN
    v_issues := array_append(v_issues, 'missing profile image reference');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid = 'hocalist.role_profiles'::regclass
      AND tgname = 'profile_avatar_validate_reference' AND NOT tgisinternal) THEN
    v_issues := array_append(v_issues, 'missing profile avatar validation');
  END IF;
  IF NOT has_function_privilege('authenticated','hocalist.profile_avatar_update(text,text,bigint,uuid)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.member_avatar(uuid)','EXECUTE')
     OR has_function_privilege('anon','hocalist.profile_avatar_update(text,text,bigint,uuid)','EXECUTE')
     OR has_function_privilege('service_role','hocalist.member_avatar(uuid)','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.profile_avatar_validate()','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.media_gateway(uuid,text,jsonb)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'profile avatar grants are wrong');
  END IF;
  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist profile avatar post-apply verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_profile_avatar_postapply$;
