f:=to_regprocedure('hocalist.profile_avatar_validate()');
IF f IS NULL OR md5(replace(pg_get_functiondef(f),chr(13),''))<>'c4f33e6dc259a1dc94915bb72d93064a' THEN RAISE EXCEPTION 'Function drift: hocalist.profile_avatar_validate()'; END IF;
FOR r IN SELECT unnest(ARRAY['anon','authenticated','service_role']) LOOP IF has_function_privilege(r,f,'EXECUTE') IS DISTINCT FROM (r=ANY(ARRAY[]::text[])) THEN RAISE EXCEPTION 'Function privilege drift: hocalist.profile_avatar_validate() %',r; END IF; END LOOP;
