IF f IS NULL OR md5(replace(pg_get_functiondef(f),chr(13),''))<>'1b3ddf4d537697fd6146560af2fd15d5' THEN RAISE EXCEPTION 'Function drift: hocalist.profile_avatar_update(text,text,bigint,uuid)'; END IF;
FOR r IN SELECT unnest(ARRAY['anon','authenticated','service_role']) LOOP IF has_function_privilege(r,f,'EXECUTE') IS DISTINCT FROM (r=ANY(ARRAY['authenticated']::text[])) THEN RAISE EXCEPTION 'Function privilege drift: hocalist.profile_avatar_update(text,text,bigint,uuid) %',r; END IF; END LOOP;
f:=to_regprocedure('hocalist.member_avatar(uuid)');
IF f IS NULL OR md5(replace(pg_get_functiondef(f),chr(13),''))<>'3e4793f8b2b0ebbd7129123879315511' THEN RAISE EXCEPTION 'Function drift: hocalist.member_avatar(uuid)'; END IF;
FOR r IN SELECT unnest(ARRAY['anon','authenticated','service_role']) LOOP IF has_function_privilege(r,f,'EXECUTE') IS DISTINCT FROM (r=ANY(ARRAY['authenticated']::text[])) THEN RAISE EXCEPTION 'Function privilege drift: hocalist.member_avatar(uuid) %',r; END IF; END LOOP;
f:=to_regprocedure('hocalist.media_read_profile(uuid,uuid)');
