FOR r IN SELECT unnest(ARRAY['anon','authenticated','service_role']) LOOP IF has_function_privilege(r,f,'EXECUTE') IS DISTINCT FROM (r=ANY(ARRAY[]::text[])) THEN RAISE EXCEPTION 'Function privilege drift: hocalist.media_read_profile(uuid,uuid) %',r; END IF; END LOOP;
f:=to_regprocedure('hocalist.media_gateway(uuid,text,jsonb)');
IF f IS NULL OR md5(replace(pg_get_functiondef(f),chr(13),''))<>'aaee68ae358c131da1aaeacc355aa6ae' THEN RAISE EXCEPTION 'Function drift: hocalist.media_gateway(uuid,text,jsonb)'; END IF;
